package com.smartsociety.platform.complaint; import com.smartsociety.platform.common.Enums.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.Instant; public interface AdminComplaintQueryRepository extends JpaRepository<Complaint,java.util.UUID>{@Query("select c from Complaint c where (:status is null or c.currentStatus=:status) and (:priority is null or c.priority=:priority) and (:categoryId is null or c.category.id=:categoryId) and (:from is null or c.createdAt>=:from) and (:to is null or c.createdAt<:to) and (:q is null or lower(c.title) like lower(concat('%',:q,'%')) or lower(c.description) like lower(concat('%',:q,'%'))) order by c.createdAt desc") Page<Complaint> search(@Param("status")ComplaintStatus status,@Param("priority")Priority priority,@Param("categoryId")Long categoryId,@Param("from")Instant from,@Param("to")Instant to,@Param("q")String q,Pageable pageable);}